    out.put("VincentSwiftblade", new NpcScripts.Entry(
        "VincentSwiftblade",
        "NPC AddOn/VincentSwiftblade.cpp",
        "VincentSwiftbladeNPC",
        "InitTalk\n\nBegin\n\"\"\nIF(CheckFlag(__FLAG_ADDON_MERCENARY_LEADER_DEFEAT)==1) \n\tConversation\n\tFORMAT(INTL(\"${npc.cpp.intl.12680}\"), USER_NAME) \nELSEIF ((USER_LEVEL>=8)&&(CheckFlag(__FLAG_ADDON_CAMP_ASSAULT)==0))\n\tConversation\n\tINTL( 12681, \"Halt adventurer! Our leader \\\"Tarnian\\\" \\\"Wolfmane\\\" needs a group of heroes to make a coordinated assault \"\n\t\"on three different camps of \\\"Olin\\\" \\\"Haad\\\"'s men at once. If you're interested, there is a very generous \"\n\t\"bounty for whoever participates in the downfall of the men's leader. Would you be interested in undertaking \"\n\t\"this mission?\")\n\tSetYesNo(AcceptMission)\nELSEIF(CheckFlag(__FLAG_ADDON_CAMP_ASSAULT)==1)\n\tConversation\n\tINTL(\"${npc.cpp.intl.12682}\") \nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.12683}\")\nENDIF \n\nYES(AcceptMission)\nConversation\nINTL(\"${npc.cpp.intl.12684}\") \n\nNO(AcceptMission)\nConversation\nINTL(\"${npc.cpp.intl.12685}\")  \n\nYesNoELSE(AcceptMission) \nConversation\nINTL(\"${npc.cpp.intl.12686}\")\nSetYesNo(AcceptMission) \n\nCommand(INTL(\"${npc.cpp.intl.12687}\")) \nINTL( 12688, \"The foul \\\"Olin\\\" \\\"Haad\\\" has enlisted the mercenaries' aid and they've taken the town under siege ever since. \"\n\"The task which lies ahead is no easy one. You will need to conduct a coordinated attack on the three camps \"\n\"located near Lighthaven's northern. Hopefully, this will eventually attracts the mercenary \"\n\"lieutenants' attention. You will then need to deal with them swiftly. This should force the leader out of his \"\n\"hideout located further north. Be wary that he is a very skillful axeman who fears no one. If you defeat the \"\n\"leader, it should destabilize the mercenaries enough for us to pierce through their defenses. You and all \"\n\"the brave soldiers who participate in his demise can then return here and collect a \\\"reward\\\".\")\nIF(CheckFlag(__FLAG_ADDON_CAMP_ASSAULT) == 1) \n\tGiveFlag(__FLAG_ADDON_CAMP_ASSAULT, 2) \nENDIF \n\nCommand(INTL(\"${npc.cpp.intl.617}\")) \n\"\"\nIF(CheckFlag(__FLAG_ADDON_MERCENARY_LEADER_DEFEAT) == 1) \n\tConversation\n\tINTL( 12689, \"I've heard of your participation in the mercenary leader's demise. Well done! Here's your reward as \"\n\t\"promised.\") \n\tGiveGoldNoEcho(500) \n\t;int nExpReward = USER_LEVEL*750;\n\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.7982}\"), nExpReward)) \n\tGiveXP(nExpReward)\n\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.12690}\")) \n\tGiveFlag(__FLAG_ADDON_MERCENARY_LEADER_DEFEAT, 0) \nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.12691}\") \nENDIF\n\nCommand2(INTL(\"${npc.cpp.intl.12692}\"),INTL(\"${npc.cpp.intl.12693}\")) \nINTL( 12694, \"Tarnian Wolfman is the only man capable of stopping \\\"Olin\\\" \\\"Haad\\\" from overthrowing us all. That is the \"\n\"reason why I chose to follow him.\") \n\nCommand(INTL(\"${npc.cpp.intl.513}\")) \nINTL(\"${npc.cpp.intl.12695}\") \n\nCommand2(INTL(\"${npc.cpp.intl.11925}\"),INTL(\"${npc.cpp.intl.11926}\")) \nINTL( 12696, \"Olin Haad is a shrewd and merciless necromancer who has visions of conquest and power. \\\"Tarnian\\\" \\\"Wolfmane\\\" \"\n\"has sworn his life to fight until Olin's demise. So did I.\") \n\nCommand(INTL(\"${npc.cpp.intl.483}\"))\nINTL(\"${npc.cpp.intl.12697}\")\n\nCommand2(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL(\"${npc.cpp.intl.12698}\") \n\nCommand5(INTL(\"${npc.cpp.intl.519}\"), INTL(\"${npc.cpp.intl.518}\"), INTL(\"${npc.cpp.intl.520}\"), INTL(\"${npc.cpp.intl.517}\"), INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.1075}\")\nBREAK\n\nDefault\n\"\"\nIF (rnd.roll( dice(1,2) ) == 1)\n\tConversation\n\tINTL(\"${npc.cpp.intl.1623}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.11825}\")\nENDIF\n\nEndTalk",
        Map.of()));
    out.put("WardenVortimer", new NpcScripts.Entry(
        "WardenVortimer",
        "NPC Remort/WardenVortimer.cpp",
        "WardenVortimerNPC",
        "InitTalk\n\nBegin\nINTL(\"${npc.cpp.intl.10658}\")\n\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.10659}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.487}\"),INTL(\"${npc.cpp.intl.488}\"))\nINTL(\"${npc.cpp.intl.10660}\") \n\nCommand2(INTL(\"${npc.cpp.intl.10661}\"),INTL(\"${npc.cpp.intl.10662}\")) \nINTL( 10663, \"Maddeus Madrigan was once a peaceful healer. He once left with a party of \"\n\"adventurers, then lost his soul while battling with Makrsh P'Tangh. Sensing he \"\n\"was gradually losing his mind, he tried building a house for mentally ill \"\n\"people, but failed to heal himself before he became stark raving mad.\")\n\nCommand3(INTL(\"${npc.cpp.intl.10664}\"),INTL(\"${npc.cpp.intl.8191}\"),INTL(\"${npc.cpp.intl.7296}\")) \n\"\"\nIF (CheckFlag(__FLAG_NUMBER_OF_REMORTS) == 0) \n\tConversation\n\tINTL( 10665, \"I'm afraid your mind is not prepared to enter in \\\"Madrigan\\\"'s house without risking \"\n\t\"permanent mental injuries.\") \nELSE \n\tIF (CheckItem(__OBJ_MAD_HOUSE_KEY) == 0) \n\t\tConversation\n\t\tINTL( 10666, \"To enter Madrigan's house, you need a key to unlock the door. I can lend you \"\t\t\n\t\t\"a key if you promise to \\\"return\\\" it once you're finished with it. Do you agree?\") \n\t\tSetYesNo(GiveKey) \n\tELSE\n\t\tConversation\n\t\tINTL( 10667, \"You already have a mad house key. If you no longer need it, you can \"\n\t\t\"\\\"return\\\" it to me.\")\n\tENDIF \nENDIF \n\nYES(GiveKey)\n\tConversation\n\tINTL(\"${npc.cpp.intl.10668}\") \n\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.10669}\")) \n\tGiveItem(__OBJ_MAD_HOUSE_KEY) \n\nNO(GiveKey) \n\tConversation\n\tINTL(\"${npc.cpp.intl.6170}\")\n\nYesNoELSE(GiveKey) \n\tConversation\n\tINTL(\"${npc.cpp.intl.10670}\")\n\tSetYesNo(GiveKey) \n\nCommand(INTL(\"${npc.cpp.intl.6167}\")) \n\"\"\nIF (CheckItem(__OBJ_MAD_HOUSE_KEY) == 0) \n\tConversation\n\tINTL(\"${npc.cpp.intl.10671}\") \nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.10672}\") \n\tSetYesNo(ReturnKey) \nENDIF \n\nYES(ReturnKey) \n\t;int nNumKeys = CheckItem(__OBJ_MAD_HOUSE_KEY); \n\tFOR(0, nNumKeys) \n\t\tTakeItem(__OBJ_MAD_HOUSE_KEY) \n\tENDFOR \n\tConversation\n\tINTL( 10673, \"Thank you. I hope you haven't been disturbed by what you've seen \"\n\t\"in the house.\") \n\tPRIVATE_SYSTEM_MESSAGE(INTL(\"${npc.cpp.intl.10674}\")) \n\nNO(ReturnKey) \n\tConversation\n\tINTL(\"${npc.cpp.intl.8109}\")\n\t\nYesNoELSE(ReturnKey) \n\tConversation\n\tINTL(\"${npc.cpp.intl.10675}\")\n\tSetYesNo(ReturnKey) \n\nCommand4(INTL(\"${npc.cpp.intl.695}\"),INTL(\"${npc.cpp.intl.696}\"),INTL(\"${npc.cpp.intl.697}\"),INTL(\"${npc.cpp.intl.698}\")) \nINTL(\"${npc.cpp.intl.10676}\") \nBREAK\n\nCommand5(INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.520}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.1075}\") \nBREAK\n\nDefault\n\"\"\nIF (rnd.roll(dice(1,2)) == 1)\n   Conversation\n   INTL(\"${npc.cpp.intl.2025}\")\nELSE\n   Conversation\n   INTL(\"${npc.cpp.intl.10677}\")\nENDIF\n\nEndTalk",
        Map.of()));
