    out.put("WindhowlSamaritan", new NpcScripts.Entry(
        "WindhowlSamaritan",
        "NPC Arakas/WindhowlSamaritan.cpp",
        "WindhowlSamaritanNPC",
        "InitTalk\n\nBegin\n\"\"\nIF (CheckFlag ( __OFFENSIVE_TALK ) < 10 )\n\tConversation\n\tINTL(\"${npc.cpp.intl.1077}\")\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.1078}\")\n\tGiveFlag ( __OFFENSIVE_TALK, (CheckFlag ( __OFFENSIVE_TALK ) - 1 ) )\n\tBREAK\nENDIF\n\nCommand2(INTL(\"${npc.cpp.intl.483}\"),INTL(\"${npc.cpp.intl.485}\"))\nINTL(\"${npc.cpp.intl.1079}\")\n\nCommand3(INTL(\"${npc.cpp.intl.489}\"),INTL(\"${npc.cpp.intl.488}\"),INTL(\"${npc.cpp.intl.487}\"))\nINTL( 1080, \"My job's to answer any questions you have... Well, almost. I don't know everything, \"\n\"but I try anyway. I'm specialized in travelling, exploration and the \\\"world\\\" in general.\")\n\nCommand3(INTL(\"${npc.cpp.intl.509}\"),INTL(\"${npc.cpp.intl.510}\"),INTL(\"${npc.cpp.intl.582}\"))\nINTL( 1081, \"It's a shame that so many have been cursed by this fiend from below! I have no cure for \"\n\"you, but perhaps you should seek someone who does. I believe she's long gone from these \"\n\"parts, but Annabelle would surely help you if she knew of your plight.\")\n\nCommand(INTL(\"${npc.cpp.intl.884}\"))\nINTL( 1082, \"By now, you're certainly aware that this is the world of Althea, and that you're walking on the \"\n\"island of Arakas in the Kingdom of Goldmoon. I'm paid to sing the merits of our good king, so \"\n\"please don't say anything bad about him. Perhaps I could tell you about the \\\"races\\\" who live here?\")\n\nCommand(INTL(\"${npc.cpp.intl.1083}\"))\nINTL( 1084, \"There are several races living in this world. Sages and Loremasters divide them between the Higher \"\n\"Races and the Lesser Races. Of the Higher Races, only humans still walk the world. Both the Elves \"\n\"and the Dwarves are gone, they say. The Lesser Races include the \\\"Goblins\\\" and the \\\"Orcs\\\". For obvious \"\n\"reasons, humans don't get along very well with the Lesser Races.\")\n\nCommand2(INTL(\"${npc.cpp.intl.539}\"),INTL(\"${npc.cpp.intl.744}\"))\nINTL( 1085, \"Goblins are by far smaller than Orcs, but they are also more numerous. They're also more savage and \"\n\"less educated. Orcs aren't very bright, mind you, but they're still a bit more evolved than the Goblins. \"\n\"Me, I'd never give the time of day to either one, I'd just run in the other direction. Those two races \"\n\"are pretty impressive in combat, and I don't have a death wish.\")\n\nCommand(INTL(\"${npc.cpp.intl.1086}\"))\nINTL( 1087, \"Ah, I see you're a clever one. Few people ask me about this. Yes, some other races speak a different \"\n\"tongue than ours. Take the Orcs, for instance. They call their language Orkentung, or something like \"\n\"that, and if you can make sense of it, you can *really* earn their trust. But then again, who'd want \"\n\"that, eh?\")\n\nCommand(INTL(\"${npc.cpp.intl.1088}\"))\nINTL( 1089, \"Hard to pronounce, eh? Well, anyway, if you're really interested, I'll tell you a secret. I know a bit \"\n\"of Orkentung, studied it with an orc who's friendly to humans. Anyway, I'm no expert, but it's not \"\n\"entirely different from our own, just pronounced really weird. For starters, they simplify some letters, \"\n\"like the *th* sounds, which become *d* sounds. Oh, and they don't have the verb *to be*. Pretty strange, \"\n\"wouldn't you say? But that's how they talk.\")\n\nCommand(INTL(\"${npc.cpp.intl.513}\"))\nINTL( 1090, \"Lighthaven's not quite as civilized as \\\"Windhowl\\\", but I would think the people are nicer there, \"\n\"and crime isn't as prevalent as it is here. And with all the monsters and bandits roaming the \"\n\"route between here and there, trade has been very bad for them. A real shame, if you ask me.\")\n\nCommand(INTL(\"${npc.cpp.intl.514}\"))\nINTL( 1091, \"We're pretty happy with the way \\\"Lord\\\" \\\"Sunrock\\\" has been running things, but even he hasn't been \"\n\"able to rid us of the bandits and monsters. Ah well. Even the mighty can fail, I guess.\")\n\nCommand(INTL(\"${npc.cpp.intl.1092}\"))\nINTL( 1093, \"Not the most gentle of fellows, for sure, but one who speaks his mind honestly and defends the \"\n\"interests of the citizens of Windhowl with an iron fist. You may not like him, but you have to \"\n\"respect his resolve. He always has a mission or two to give to people, so perhaps you should visit \"\n\"him and offer your services.\")\n\nCommand(INTL(\"${npc.cpp.intl.888}\"))\nINTL( 1094, \"There's one of us Samaritans in almost every city. We answer your questions. Of course, you could \"\n\"always read the manual, but in case you didn't, we're there for you.\")\n\nCommand2(INTL(\"${npc.cpp.intl.890}\"),INTL(\"${npc.cpp.intl.891}\"))\nINTL( 1095, \"Cities are fairly save. On the island of Arakas--where we are right now--you have only two cities: \"\n\"\\\"Lighthaven\\\" and \\\"Windhowl\\\". We don't know much about the other cities in the world.\")\n\nCommand2(INTL(\"${npc.cpp.intl.700}\"),INTL(\"${npc.cpp.intl.1096}\"))\nINTL( 1097, \"I don't know much about magic myself, but there are dozens of skilled magicians who can teach you \"\n\"more about it. You just have to ask the right questions, of course. Me, I just know it's got \"\n\"something to do with \\\"Karma\\\", but I've never cared much for magic, so don't ask me any more.\")\n\nCommand(INTL(\"${npc.cpp.intl.1886}\"))\nINTL(\"${npc.cpp.intl.1099}\")\n\nCommand(INTL(\"${npc.cpp.intl.896}\"))\nINTL( 1100, \"Quests, as I'm sure you know by now, abound, and the brave and mighty adventurers such as yourself \"\n\"are never out of work if they wish to undertake them. You just have to know who to ask, what to say \"\n\"and what items or information they need. Also, you should distinguish minor quests the major one. \"\n\"Indeed, there's something tragic happening in the world, and if you really want to do something about \"\n\"it, just visit Balork in the dungeon below the temple in Lighthaven, and you'll know what I mean.\")\n\nCommand4(INTL(\"${npc.cpp.intl.695}\"),INTL(\"${npc.cpp.intl.696}\"),INTL(\"${npc.cpp.intl.697}\"),INTL(\"${npc.cpp.intl.698}\"))\nINTL(\"${npc.cpp.intl.1101}\")\nGiveFlag ( __OFFENSIVE_TALK , ( CheckFlag ( __OFFENSIVE_TALK ) + 1 ) )\nBREAK\n\nCommand5(INTL(\"${npc.cpp.intl.519}\"),INTL(\"${npc.cpp.intl.521}\"),INTL(\"${npc.cpp.intl.518}\"),INTL(\"${npc.cpp.intl.517}\"),INTL(\"${npc.cpp.intl.520}\"))\nINTL(\"${npc.cpp.intl.933}\")\nBREAK\n\nDefault\nINTL( 1102, \"I'm sorry, could you rephrase that? I'm somewhat old and easily confused by young people \"\n\"such as yourself.\")\n\nEndTalk",
        Map.of()));
    out.put("WindhowlSentry", new NpcScripts.Entry(
        "WindhowlSentry",
        "NPC AddOn/WindhowlSentry.cpp",
        "WindhowlSentryNPC",
        "InitTalk\n\nBegin\n\"\"\nIF(USER_LEVEL < 50)\n\tConversation\n\tINTL(\"${npc.cpp.intl.12699}\")\n\tBREAK\nELSE\n\tIF(CheckFlag(__FLAG_ADDON_USER_HAS_KILLED_CARMAN) == 1)\n\t\tIF(CheckFlag(__FLAG_ADDON_USER_REWARDED_FOR_KILLING_CARMAN) == 0)\n\t\t\tIF(CheckFlag(__FLAG_ADDON_USER_SPAWNED_CARMAN) == 1)\n\t\t\t\tConversation\n\t\t\t\tINTL( 12700, \"I must admit, I wasn't sure if you would be able to pull it off. Well done! Now, to show the \"\n\t\t\t\t\"town's gratitude, I have a special \\\"reward\\\" for you.\")\n\t\t\tELSE\n\t\t\t\tConversation\n\t\t\t\tINTL( 12701, \"So, you also participated in the battle against Hel, did you? Very well, I have a \\\"reward\\\" \"\n\t\t\t\t\"for you as well.\")\n\t\t\tENDIF\n\t\tELSE\n\t\t\tConversation\n\t\t\tINTL( 12702, \"I thank you for helping us get rid of that menace once again. I just hope it's for good \"\n\t\t\t\"this time.\")\n\t\tENDIF\n\tELSE\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.12703}\")\n\tENDIF\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.554}\"))\n\"\"\nIF(CheckGlobalFlag(__GLOBAL_FLAG_ADDON_CARMAN_PRESENT) == 0)\n\tConversation\n\tINTL( 12704, \"A Seraph called Hel has been plaguing this town for awhile now, abducting people when they wander \"\n\t\"outside the gates and performing all kinds of twisted forms of torture for the sheer pleasure of it. \"\n\t\"Unfortunately, I can't leave my post here because I have to make sure no one else wanders outside. \"\n\t\"That's why I need you to \\\"take\\\" \\\"care\\\" of her for me.\")\nELSE\n\tConversation\n\tINTL( 12705, \"I already sent someone to confront her but knowing her, it's going to take a lot more to defeat her. \"\n\t\"If you're up for a tough fight, she's just north of town.\")\n\tGiveFlag(__FLAG_ADDON_USER_SPAWNED_CARMAN, 1)\nENDIF\n\nCmdAND(INTL(\"${npc.cpp.intl.12706}\"), INTL(\"${npc.cpp.intl.12707}\"))\n\"\"\nIF(CheckGlobalFlag(__GLOBAL_FLAG_ADDON_CARMAN_PRESENT) == 0)\n\tConversation\n\tINTL( 12708, \"You must confront her and make her stop this madness, no matter what the cost. What do you say? Will \"\n\t\"you do this for the townspeople of Windhowl?\")\n\tSetYesNo(Accept)\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.12709}\")\nENDIF\n\nYES(Accept)\n\tConversation\n\tINTL( 12710, \"Great! I should warn you that you'll probably need to bring several friends to deal with her if things \"\n\t\"get ugly. Hell, if you have access to an army, bring it along. Don't try fighting her alone...\")\n\tSUMMON(\"CARMANSPAWNER\", 1663, 1040)\n\tGiveFlag(__FLAG_ADDON_USER_SPAWNED_CARMAN, 1)\n\tGiveGlobalFlag(__GLOBAL_FLAG_ADDON_CARMAN_PRESENT, 1)\nNO(Accept)\n\tConversation\n\tINTL(\"${npc.cpp.intl.12711}\")\nYesNoELSE(Accept)\n\tConversation\n\tINTL(\"${npc.cpp.intl.12712}\")\n\tSetYesNo(Accept)\n\nCommand(INTL(\"${npc.cpp.intl.617}\"))\n\"\"\nIF(CheckFlag(__FLAG_ADDON_USER_HAS_KILLED_CARMAN) == 1)\n\tIF(CheckFlag(__FLAG_ADDON_USER_REWARDED_FOR_KILLING_CARMAN) == 0)\n\t\tIF(CheckFlag(__FLAG_ADDON_USER_SPAWNED_CARMAN) == 1)\n\t\t\tConversation\n\t\t\tINTL( 12713, \"It is with great honor that I present this reward to you. All the townspeople pitched in, so I \"\n\t\t\t\"hope it's enough.\")\n\t\t\tGiveGold(USER_LEVEL*500)\n\t\t\tGiveXP((USER_LEVEL^2)*100)\n\t\t\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.12714}\"), (USER_LEVEL^2)*100))\n\t\t\tGiveFlag(__FLAG_ADDON_USER_REWARDED_FOR_KILLING_CARMAN, 1)\n\t\tELSE\n\t\t\tConversation\n\t\t\tINTL( 12715, \"It is with great honor that I present this reward to you. All the townspeople pitched in, so I \"\n\t\t\t\"hope it's enough.\")\n\t\t\tGiveGold(USER_LEVEL*500)\n\t\t\tGiveXP((USER_LEVEL^2)*100)\n\t\t\tPRIVATE_SYSTEM_MESSAGE(FORMAT(INTL(\"${npc.cpp.intl.12714}\"), (USER_LEVEL^2)*100))\n\t\t\tGiveFlag(__FLAG_ADDON_USER_REWARDED_FOR_KILLING_CARMAN, 1)\n\t\tENDIF\n\tELSE\n\t\tConversation\n\t\tINTL(\"${npc.cpp.intl.12716}\")\n\tENDIF\n\tGiveFlag(__FLAG_ADDON_USER_HAS_KILLED_CARMAN, 0)\n\tGiveFlag(__FLAG_ADDON_USER_SPAWNED_CARMAN, 0)\nELSE\n\tConversation\n\tINTL(\"${npc.cpp.intl.12717}\")\nENDIF\n\nCommand(INTL(\"${npc.cpp.intl.489}\"))\nINTL(\"${npc.cpp.intl.12718}\")\n\nCommand5(INTL(\"${npc.cpp.intl.519}\"), INTL(\"${npc.cpp.intl.518}\"), INTL(\"${npc.cpp.intl.520}\"), INTL(\"${npc.cpp.intl.517}\"), INTL(\"${npc.cpp.intl.521}\"))\nINTL(\"${npc.cpp.intl.12719}\")\nBREAK\n\nDefault\nINTL(\"${npc.cpp.intl.12709}\")\n\nEndTalk",
        Map.ofEntries(
              Map.entry("OnInitialise", "\n\tNPCstructure::OnInitialise( UNIT_FUNC_PARAM );\n\n\tWorldPos wlPos = { 0,0,0 };\n\tself->SetDestination( wlPos );\n\tself->Do( nothing );\n\tself->SetCanMove( FALSE );\n")
          )));
